tbl(con, "HallOfFame") |&gt;
  filter(inducted == "Y") |&gt;
  inner_join(
    tbl(con, "Managers"),
    by = "playerID"
  ) |&gt;
select(playerID, G, W, L) |&gt;
group_by(playerID) |&gt;
summarize(G_managed = sum(G, na.rm = TRUE),
Total_W = sum(W, na.rm = TRUE),
Total_L = sum(L, na.rm = TRUE)) |&gt;
  collect() |&gt;
  mutate(
    win_percentage = Total_W / G_managed
  ) |&gt;
  arrange(desc(win_percentage))

